-- Talent plans: an ordered list of picks for the player's class and spec, shown in the hub's Talents section (View.lua) and
-- on the client's talent frame (Overlay.lua).
--
-- Forever's talents are a C_Traits tree per class (three spec columns, tier
-- gates on points spent in a column, arrows). Builds.lua (generated by
-- `talents build` from talents/forever/) registers the plans with a snapshot
-- of the tree they were checked against. At run time the snapshot is checked
-- against the live tree: a node whose ID moved is found again by its spell
-- (or, when the client gives none, its name) and rank count; a plan with a
-- talent that is gone is shown as out of date instead of guessing. Names
-- shown to the player are the client's, so they follow its language.
--
-- Plans are a sequence, not a schedule: the addon does not assume when a
-- point arrives (a Legacy talent such as Talented (Adventure) grants them
-- earlier). Points granted and spent come from the game
-- (C_Traits.GetTreeCurrencyInfo); one point a level from 10 is only the
-- fallback when the client cannot say. Whenever a point is unspent the next
-- pick is the one to take.
--
--   T.Current() -> { data, build, valid, granted, state, staged } | nil, reason
--     state: the plan against learned ranks; staged: against the ranks
--     shown in the frame (learned plus not yet applied)
--   T.State(build, ranks, level, granted) -> plan progress (pure)
--   T.Replay(data, build) -> errors under the snapshot's rules (pure)
--   T.Validate(data, live) -> { map = plan node -> live node, names = plan node -> live name, moved, missing, ok }
--
-- Fires TALENTS_UPDATED after every refresh. Client calls go through
-- T.Client so the tests can stand in for the game.

local ADDON, ns = ...
local L = ns.L
local max, min, pairs, ipairs, type, pcall, format = math.max, math.min, pairs, ipairs, type, pcall, string.format

local T = {}
ns.Talents = T

T.FIRST_LEVEL = 10 -- the fallback only: one point a level from here

ns.RegisterDefaults("talents", {
	enabled = true,
	overlay = true, -- marks on the talent frame
	badges = true, -- the pick number on each talent
	tooltip = true,
	reminder = true, -- a chat line when a point is waiting
})

function T.Get(key) return ns.Get("talents." .. key) end

---------------------------------------------------------------------------
-- Plans
---------------------------------------------------------------------------

local registry = {} -- class -> data

local function playerClass()
	local _, cls = UnitClass("player")
	return cls
end

-- Builds.lua's compact rows -> records. Builds.lua registers every class;
-- only the player's class is kept, so the other classes' plans (most of the
-- file) are left to the garbage collector instead of being expanded and held
-- for the session. When the client cannot name the class yet, every class is
-- kept, as before.
function T.Register(data)
	local mine = playerClass()
	if mine and data.class ~= mine then return end
	for id, n in pairs(data.nodes) do
		data.nodes[id] = { id = id, entry = n[1], max = n[2], spell = n[3], spec = n[4], row = n[5], col = n[6], name = n[7] }
	end
	for _, b in ipairs(data.builds) do
		local picks = {}
		for i, p in ipairs(b.picks) do picks[i] = { order = i, node = p[1], rank = p[2] } end
		b.picks, b.data, b.specName = picks, data, L[data.specs[b.spec]]
	end
	registry[data.class] = data
end

function T.Data(cls) return registry[cls or playerClass()] end

-- The rank an arrow's source needs: data.prereq, from tools/lib/talents/build.js.
function T.PrereqRank(data, node)
	return data.prereq == "started" and 1 or node.max
end

-- Every pick under the snapshot's rules (the tool's replay, again here so a
-- hand-edited Builds.lua cannot slip through): one point a pick, the next
-- rank, the tier gate met, an arrow into it satisfied (of several, any one).
function T.Replay(data, build)
	local errors, ranks = {}, {}
	local function spent(g)
		local s = 0
		for _, id in ipairs(data.groups[g] or {}) do s = s + (ranks[id] or 0) end
		return s
	end
	for i, p in ipairs(build.picks) do
		local n = data.nodes[p.node]
		local function err(text) errors[#errors + 1] = format("%s #%d (%s): %s", build.key, p.order, n and n.name or tostring(p.node), text) end
		if not n then
			err("not in the tree")
		else
			local have = ranks[p.node] or 0
			if p.rank ~= have + 1 or p.rank > n.max then err(format("rank %d after %d of %d", p.rank, have, n.max)) end
			for _, g in ipairs(data.gates[p.node] or {}) do
				if spent(g[1]) < g[2] then err(format("needs %d points in the tree", g[2])) end
			end
			-- Several arrows into one talent: any one of them opens it.
			local into, open = {}, false
			for _, e in ipairs(data.edges) do
				if e[2] == p.node then
					local from = data.nodes[e[1]]
					into[#into + 1] = from.name
					if (ranks[e[1]] or 0) >= T.PrereqRank(data, from) then open = true end
				end
			end
			if #into > 0 and not open then err("needs " .. table.concat(into, " or ")) end
			ranks[p.node] = p.rank
		end
	end
	return errors
end

-- Points granted at a level when the client cannot say: one a level from
-- FIRST_LEVEL, up to the plan's length.
function T.FallbackPoints(level, total)
	return max(0, min(level - T.FIRST_LEVEL + 1, total))
end

-- Plan progress for ranks (node -> rank, plan IDs). granted: the points the
-- game has given (spent plus unspent, from the tree's currency); nil falls
-- back to the level.
--   done, total, next (the first pick not met), nodeNext (node -> its first
--   pick not met), offPlan (node -> ranks beyond the plan), spent, points
--   (granted), unspent, source ("currency" | "level"), status: "early" (no
--   points yet) | "offplan" | "complete" | "behind" (a point to spend: take
--   the next pick) | "onplan" (waiting for the next point)
function T.State(build, ranks, level, granted)
	local s = { done = 0, total = #build.picks, offPlan = {}, nodeNext = {}, spent = 0, level = level }
	local planned = {}
	for _, p in ipairs(build.picks) do planned[p.node] = max(planned[p.node] or 0, p.rank) end
	local off = false
	for id, r in pairs(ranks) do
		s.spent = s.spent + r
		if r > (planned[id] or 0) then
			s.offPlan[id] = r - (planned[id] or 0)
			off = true
		end
	end
	for _, p in ipairs(build.picks) do
		if (ranks[p.node] or 0) >= p.rank then
			s.done = s.done + 1
		else
			s.next = s.next or p
			s.nodeNext[p.node] = s.nodeNext[p.node] or p
		end
	end
	if type(granted) == "number" then
		s.points, s.source = max(granted, s.spent), "currency"
	else
		s.points, s.source = max(T.FallbackPoints(level or 0, s.total), s.spent), "level"
	end
	s.unspent = max(0, s.points - s.spent)
	if s.points == 0 then
		s.status = "early"
	elseif off then
		s.status = "offplan"
	elseif not s.next then
		s.status = "complete"
	elseif s.unspent > 0 then
		s.status = "behind"
	else
		s.status = "onplan"
	end
	return s
end

---------------------------------------------------------------------------
-- The live tree
---------------------------------------------------------------------------

local Client = {}
T.Client = Client

local function call(fn, ...)
	if not fn then return nil end
	local ok, a, b = pcall(fn, ...)
	if ok then return a, b end
end

function Client.ConfigID() return C_ClassTalents and call(C_ClassTalents.GetActiveConfigID) end
function Client.TreeNodes(tree) return C_Traits and call(C_Traits.GetTreeNodes, tree) end
function Client.NodeInfo(config, id) return C_Traits and call(C_Traits.GetNodeInfo, config, id) end
function Client.Level() return UnitLevel("player") or 1 end
function Client.InCombat() return InCombatLockdown and InCombatLockdown() or false end

-- The points the game has granted on the tree (spent plus unspent), from
-- its currency as the Recorder reads it; nil when the client cannot say.
function Client.Granted(config, tree)
	local list = C_Traits and C_Traits.GetTreeCurrencyInfo and call(C_Traits.GetTreeCurrencyInfo, config, tree, false)
	if type(list) ~= "table" or not list[1] then return nil end
	local total
	for _, c in ipairs(list) do
		if type(c) == "table" and type(c.quantity) == "number" then
			total = (total or 0) + c.quantity + (type(c.spent) == "number" and c.spent or 0)
		end
	end
	return total
end

-- An entry's spell ID and its name in the client's language.
function Client.Entry(config, entryID)
	local e = entryID and C_Traits and call(C_Traits.GetEntryInfo, config, entryID)
	local d = e and e.definitionID and call(C_Traits.GetDefinitionInfo, e.definitionID)
	if not d then return nil end
	local spell = d.spellID
	if d.overrideName and d.overrideName ~= "" then return spell, d.overrideName end
	if not spell then return nil end
	if C_Spell and C_Spell.GetSpellName then return spell, (call(C_Spell.GetSpellName, spell)) end
	return spell, GetSpellInfo and (call(GetSpellInfo, spell))
end

-- -> { config, nodes = { id = { active, current, max, spell, name } } } | nil, reason
function T.Read(data)
	local config = Client.ConfigID()
	if not config then return nil, "noconfig" end
	local ids = Client.TreeNodes(data.tree)
	if type(ids) ~= "table" or #ids == 0 then return nil, "notree" end
	local nodes = {}
	for _, id in ipairs(ids) do
		local info = Client.NodeInfo(config, id)
		if info and info.ID and info.ID ~= 0 then
			local entry = (info.activeEntry and info.activeEntry.entryID) or (info.entryIDs and info.entryIDs[1])
			local spell, name = Client.Entry(config, entry)
			nodes[id] = { active = info.activeRank or 0, current = info.currentRank or info.activeRank or 0, max = info.maxRanks or 0, spell = spell, name = name }
		end
	end
	return { config = config, nodes = nodes, granted = Client.Granted(config, data.tree) }
end

-- Whether a live node is the snapshot's talent: the spell ID when the
-- client gives one (the same in every language), else the name.
local function same(l, n)
	if l.max ~= n.max then return false end
	if l.spell and n.spell then return l.spell == n.spell end
	return not l.name or l.name == n.name
end

-- The snapshot's nodes on the live tree: by ID when the rank count and the
-- spell (or name) agree, else by spell and rank count, else by name and
-- rank count when the client gives no spell.
function T.Validate(data, live)
	local v = { map = {}, back = {}, names = {}, moved = 0, missing = {}, ok = true }
	local bySpell, byName = {}, {}
	local function index(t, k, id) t[k] = t[k] == nil and id or false end -- false: not unique
	for id, n in pairs(live.nodes) do
		if n.spell then index(bySpell, n.spell .. "#" .. n.max, id) end
		if n.name then index(byName, n.name .. "#" .. n.max, id) end
	end
	local planned = {}
	for _, b in ipairs(data.builds) do for _, p in ipairs(b.picks) do planned[p.node] = true end end
	for id, n in pairs(data.nodes) do
		local l = live.nodes[id]
		local hit
		if l and same(l, n) then
			hit = id
		else
			hit = (n.spell and bySpell[n.spell .. "#" .. n.max]) or nil
			if not hit then
				local h = byName[n.name .. "#" .. n.max]
				if h and not (live.nodes[h].spell and n.spell) then hit = h end
			end
			if hit then v.moved = v.moved + 1 end
		end
		if hit then
			v.map[id], v.back[hit] = hit, id
			v.names[id] = live.nodes[hit].name
		elseif planned[id] then
			v.missing[#v.missing + 1] = n.name
			v.ok = false
		end
	end
	table.sort(v.missing)
	return v
end

---------------------------------------------------------------------------
-- The chosen plan
---------------------------------------------------------------------------

local function char()
	local s = ns.CharState()
	if type(s.talents) ~= "table" then s.talents = {} end
	return s.talents
end

-- "auto" (follow the spec) or a plan key.
function T.Choice() return char().build or "auto" end
function T.Choose(key)
	char().build = (key and key ~= "auto") and key or nil
	T.Refresh()
end

function T.BuildByKey(data, key)
	for _, b in ipairs(data.builds) do if b.key == key then return b end end
end

-- The chosen plan, else the Gear module's spec, else the column with the
-- most points, else the first plan.
function T.ActiveBuild(data, ranks)
	local b = T.BuildByKey(data, T.Choice())
	if b then return b, "chosen" end
	local Gear = ns.Gear
	local spec = Gear and Gear.GetSpec and (Gear.GetSpec())
	if spec then
		b = T.BuildByKey(data, spec)
		if b then return b, "spec" end
	end
	if ranks then
		local per, best = {}, nil
		for id, r in pairs(ranks) do
			local n = data.nodes[id]
			if n and r > 0 then per[n.spec] = (per[n.spec] or 0) + r end
		end
		for s, c in pairs(per) do if not best or c > per[best] then best = s end end
		for _, x in ipairs(data.builds) do if x.spec == best then return x, "points" end end
	end
	return data.builds[1], "default"
end

---------------------------------------------------------------------------
-- Refresh
---------------------------------------------------------------------------

local current, reason

-- Live ranks on the plan's IDs.
local function ranksOf(valid, live, field)
	local out = {}
	for liveID, n in pairs(live.nodes) do
		local id = valid.back[liveID]
		if id and n[field] > 0 then out[id] = n[field] end
	end
	return out
end

function T.Refresh()
	current, reason = nil, nil
	local data = T.Data()
	if not T.Get("enabled") then
		reason = "off"
	elseif not data then
		reason = "class"
	else
		local live, why = T.Read(data)
		if not live then
			reason = why
		else
			local valid = T.Validate(data, live)
			local active = ranksOf(valid, live, "active")
			local build = T.ActiveBuild(data, active)
			local level = Client.Level()
			-- Granted points do not change with staged ranks: the frame's
			-- unspent count is granted minus the ranks it shows.
			local granted = live.granted
			current = { data = data, build = build, live = live, valid = valid, level = level, granted = granted }
			if valid.ok then
				current.state = T.State(build, active, level, granted)
				current.staged = T.State(build, ranksOf(valid, live, "current"), level, granted)
			else
				reason = "stale"
			end
		end
	end
	ns.Fire("TALENTS_UPDATED")
	return current, reason
end

function T.Current() return current, reason end

-- One refresh a frame however many trait events arrive together.
local queued = false
function T.Queue()
	if queued then return end
	queued = true
	local function run()
		queued = false
		T.Refresh()
	end
	if C_Timer and C_Timer.After then C_Timer.After(0, run) else run() end
end

-- A plan node's name: the client's (its language) when the live tree has
-- the talent, else the snapshot's.
function T.NodeName(data, id, valid)
	return valid and valid.names[id] or data.nodes[id].name
end

-- The plan's text for a pick: "Seal of Command 1/1".
function T.PickText(data, pick, valid)
	local n = data.nodes[pick.node]
	return format("%s %d/%d", T.NodeName(data, pick.node, valid), pick.rank, n.max)
end

-- After a level-up, once the client has granted the point (if any: points
-- can come earlier or later than one a level).
local function remind()
	local c = T.Refresh()
	local s = c and c.state
	if not (s and T.Get("reminder")) or s.unspent == 0 or not s.next or s.status ~= "behind" then return end
	ns.Print(format(L["Talent point: %s (%s plan)."], T.PickText(c.data, s.next, c.valid), c.build.specName))
end

ns.OnLogin(function()
	for _, ev in ipairs({ "TRAIT_CONFIG_UPDATED", "TRAIT_NODE_CHANGED", "TRAIT_TREE_CURRENCY_INFO_UPDATED", "ACTIVE_TALENT_GROUP_CHANGED", "PLAYER_TALENT_UPDATE" }) do
		ns.RegisterEvent(ev, T.Queue)
	end
	ns.RegisterEvent("PLAYER_LEVEL_UP", function()
		if C_Timer and C_Timer.After then C_Timer.After(1, remind) else remind() end
	end)
	ns.On("GEAR_UPDATED", function(what) if what == "spec" then T.Queue() end end)
	T.Refresh()
end)

function T.Show() ns.Fire("SHOW_TALENTS") end

ns.RegisterCommand("talents", function() T.Show() end, L["Open your talent plan"])
